import React, { useState } from 'react';

function CartPage({ cart, onClearCart, onPlaceOrder }) {
    const [successMessage, setSuccessMessage] = useState('');
    const [showForm, setShowForm] = useState(false);
    const [userInfo, setUserInfo] = useState({
        name: '',
        address: '',
        phone: '',
        city: '',
        paymentMethod: '',
        deliveryOption: '',
    });

    const totalAmount = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

    const handlePlaceOrder = async () => {
        if (!userInfo.name || !userInfo.address || !userInfo.phone || !userInfo.city || !userInfo.paymentMethod || !userInfo.deliveryOption) {
            alert('Please fill in all the required information.');
            return;
        }

        try {
            await onPlaceOrder({ ...userInfo, totalAmount });
            setSuccessMessage('?? Your order has been placed successfully!');
            setTimeout(() => setSuccessMessage(''), 5000);
            onClearCart();
            setShowForm(false);
        } catch (err) {
            console.error('Error placing order:', err.message);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUserInfo((prevInfo) => ({
            ...prevInfo,
            [name]: value,
        }));
    };

    return (
        <div className="cart-container bg-gray-100 min-h-screen py-10 px-4">
            <h1 className="text-4xl font-bold text-center text-green-600 mb-8">Your Cart</h1>

            {successMessage && (
                <div className="max-w-lg mx-auto bg-green-100 border border-green-500 text-green-700 p-4 rounded-lg shadow-md text-center mb-8">
                    <p className="text-lg font-semibold">{successMessage}</p>
                </div>
            )}

            {cart.length === 0 ? (
                <p className="text-center text-gray-500 text-lg">Your cart is empty. Start shopping now!</p>
            ) : (
                <>
                    <div className="cart-items max-w-4xl mx-auto flex flex-col gap-6 mb-10">
                        {cart.map((item) => (
                            <div
                                key={item.id}
                                className="flex items-center bg-white p-4 rounded-lg shadow-md"
                            >
                                <img
                                    src={item.image}
                                    alt={item.name}
                                    className="w-24 h-24 object-cover rounded-md"
                                />
                                <div className="ml-4 flex-1">
                                    <h3 className="text-lg font-semibold text-gray-800">{item.name}</h3>
                                    <p className="text-gray-600">
                                        ${item.price} x {item.quantity}
                                    </p>
                                    <p className="text-green-600 font-bold">
                                        Total: ${item.price * item.quantity}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="cart-summary max-w-lg mx-auto bg-white p-6 rounded-lg shadow-lg text-center">
                        <h2 className="text-2xl font-bold text-gray-800 mb-4">
                            Total Amount: <span className="text-green-600">${totalAmount.toFixed(2)}</span>
                        </h2>

                        {!showForm ? (
                            <button
                                onClick={() => setShowForm(true)}
                                className="w-full bg-green-500 hover:bg-green-600 text-white py-3 px-6 rounded-lg font-semibold transition duration-200 ease-in-out shadow-md"
                            >
                                Proceed to Checkout
                            </button>
                        ) : (
                            <div className="space-y-6 text-left">
                                <h3 className="text-lg font-bold text-gray-800 mb-4">Enter Your Information</h3>
                                <input
                                    type="text"
                                    name="name"
                                    placeholder="Your Full Name"
                                    value={userInfo.name}
                                    onChange={handleInputChange}
                                    className="w-full p-3 border rounded-lg shadow-sm focus:ring-green-500 focus:border-green-500"
                                    required
                                />
                                <input
                                    type="text"
                                    name="address"
                                    placeholder="Your Address"
                                    value={userInfo.address}
                                    onChange={handleInputChange}
                                    className="w-full p-3 border rounded-lg shadow-sm focus:ring-green-500 focus:border-green-500"
                                    required
                                />
                                <input
                                    type="tel"
                                    name="phone"
                                    placeholder="Your Phone Number"
                                    value={userInfo.phone}
                                    onChange={handleInputChange}
                                    className="w-full p-3 border rounded-lg shadow-sm focus:ring-green-500 focus:border-green-500"
                                    required
                                />
                                <input
                                    type="text"
                                    name="city"
                                    placeholder="City"
                                    value={userInfo.city}
                                    onChange={handleInputChange}
                                    className="w-full p-3 border rounded-lg shadow-sm focus:ring-green-500 focus:border-green-500"
                                    required
                                />
                                <select
                                    name="deliveryOption"
                                    value={userInfo.deliveryOption}
                                    onChange={handleInputChange}
                                    className="w-full p-3 border rounded-lg shadow-sm focus:ring-green-500 focus:border-green-500"
                                    required
                                >
                                    <option value="" disabled>
                                        Select Delivery Option
                                    </option>
                                    <option value="standard">Standard Delivery</option>
                                    <option value="express">Express Delivery</option>
                                </select>
                                <select
                                    name="paymentMethod"
                                    value={userInfo.paymentMethod}
                                    onChange={handleInputChange}
                                    className="w-full p-3 border rounded-lg shadow-sm focus:ring-green-500 focus:border-green-500"
                                    required
                                >
                                    <option value="" disabled>
                                        Select Payment Method
                                    </option>
                                    <option value="creditCard">Credit Card</option>
                                    <option value="paypal">PayPal</option>
                                    <option value="cod">Cash on Delivery</option>
                                </select>
                                <button
                                    onClick={handlePlaceOrder}
                                    className="mt-4 w-full bg-green-500 hover:bg-green-600 text-white py-3 px-6 rounded-lg font-semibold transition duration-200 ease-in-out shadow-md"
                                >
                                    Place Order
                                </button>
                            </div>
                        )}
                    </div>
                </>
            )}
        </div>
    );
}

export default CartPage;
